import { FormulaType } from "./formula-type.enum";
import { SpellCounter } from "./spell-block-model";

export interface StatModifier {
  stat:
    | 'strength' | 'dexterity' | 'speed' | 'intelligence' | 'constitution' | 'chill'
    | 'mana' | 'life' | 'energy' | 'focus'
    // Derived targets — folded into the derived calculations by TrueStatsService.
    // 'movement' is flat Bewegung (hex steps), NOT a speed buff.
    | 'movement' | 'grundbonus' | 'reaktion' | 'armorMalus' | 'armorNegation';
  amount: number;
}

export class SkillBlock {
  name!: string;
  class!: string;
  description!: string;
  type!: 'active' | 'passive' | 'dice_bonus' | 'stat_bonus' | 'talent_bonus';
  enlightened!: boolean;
  level?: number;
  skillId?: string;
  statModifiers?: StatModifier[];
  libraryOrigin?: string;
  libraryOriginName?: string;
  // Source category
  skillSource?: 'class' | 'race' | 'custom';
  // User-set disabled flag (DM can disable individual skills)
  disabled?: boolean;
  // Custom cost for active skills (falls back to definition lookup if not set)
  cost?: { type: 'mana' | 'energy' | 'life'; amount: number; perRound?: boolean };
  actionType?: 'Aktion' | 'Bonusaktion' | 'Keine Aktion' | 'Reaktion';
  // Optional inline action macro (overrides cost popup when set)
  embeddedMacro?: import('./action-macro.model').ActionMacro;
  // Simpler skill macro (MacroAction, configured in editor)
  embeddedMacroAction?: import('./macro-action.model').MacroAction;
  // FailScript action (new); takes precedence over the legacy macros above
  script?: string;
  // Perpetual: while this skill is active, its script's effectActive block is collected
  // continuously (like a status effect) instead of running once on activation.
  perpetual?: boolean;
  // Set when this skill was granted by a race (holds race id) - used for cleanup on race change
  sourceRaceId?: string;
  // Configurable counter bars shown while skill is active
  counters?: SpellCounter[];
  // Effect-bound: derived from an active effect's effectActive grantSkill (not persisted).
  derived?: boolean;
  /** Granted by an equipped item (derived, not persisted). */
  isItemBased?: boolean;
}